from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFF = sum(nums)
        target = k + OFF
        if target < 0 or target > 2 * OFF:
            return -1

        # DP2: subsequences tracking only parity and whether a zero was included
        d2 = [[0, 0], [0, 0]]  # d2[parity][hasZero] = bitmask of reachable sums (+OFF)
        # DP1: subsequences with no zeros, tracking (parity, product<=limit)
        d1 = {}

        for x in nums:
            # ---- DP2 ----
            n2 = [[0, 0], [0, 0]]
            for p in (0, 1):
                for h in (0, 1):
                    m = d2[p][h]
                    if m:
                        nh = h | (1 if x == 0 else 0)
                        if p == 0:
                            n2[1][nh] |= m << x
                        else:
                            n2[0][nh] |= m >> x
            n2[1][1 if x == 0 else 0] |= 1 << (x + OFF)
            for p in (0, 1):
                for h in (0, 1):
                    if n2[p][h]:
                        d2[p][h] |= n2[p][h]

            # ---- DP1 ----
            if x >= 1:
                nd = {}
                for key, m in d1.items():
                    p, pr = key
                    npr = pr * x
                    if npr > limit:
                        continue
                    if p == 0:
                        nk = (1, npr)
                        nm = m << x
                    else:
                        nk = (0, npr)
                        nm = m >> x
                    if nm:
                        if nk in nd:
                            nd[nk] |= nm
                        else:
                            nd[nk] = nm
                if x <= limit:
                    nk = (1, x)
                    nm = 1 << (x + OFF)
                    if nk in nd:
                        nd[nk] |= nm
                    else:
                        nd[nk] = nm
                for key, m in nd.items():
                    if key in d1:
                        d1[key] |= m
                    else:
                        d1[key] = m

        ans = -1
        if ((d2[0][1] | d2[1][1]) >> target) & 1:
            ans = 0
        for key, m in d1.items():
            pr = key[1]
            if pr > ans and ((m >> target) & 1):
                ans = pr
        return ans

