class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def f(n):
            if n <= 0:
                return 0
            total = 0
            k = 1
            lo = 1
            while lo <= n:
                hi = lo * 4 - 1
                if hi > n:
                    hi = n
                total += (hi - lo + 1) * k
                k += 1
                lo *= 4
            return total

        def d(x):
            k = 0
            while x > 0:
                x //= 4
                k += 1
            return k

        ans = 0
        for l, r in queries:
            S = f(r) - f(l - 1)
            ans += max((S + 1) // 2, d(r))
        return ans

