class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N):
            if N <= 0:
                return 0
            ds = list(map(int, str(N)))
            n = len(ds)

            @lru_cache(maxsize=None)
            def dp(pos, s, p, tight, started):
                if pos == n:
                    if not started:
                        return 0
                    if p == 0:
                        return 1
                    return 1 if p % s == 0 else 0
                total = 0
                hi = ds[pos] if tight else 9
                for d in range(0, hi + 1):
                    nt = tight and (d == hi)
                    if not started and d == 0:
                        total += dp(pos + 1, 0, 1, nt, False)
                    else:
                        total += dp(pos + 1, s + d, p * d, nt, True)
                return total

            res = dp(0, 0, 1, True, False)
            dp.cache_clear()
            return res

        return count(r) - count(l - 1)

