class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n
        children = [{}]
        cnt = [0]
        depth = [0]
        for w in words:
            node = 0
            cnt[0] += 1
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                cnt[node] += 1
        maxdepth = max(depth)
        cntd = [0] * (maxdepth + 1)
        for v in range(len(cnt)):
            if cnt[v] >= k:
                cntd[depth[v]] += 1
        maxd = 0
        for d in range(maxdepth + 1):
            if cntd[d] > 0:
                maxd = d
        best2 = [0] * (maxdepth + 1)
        cur = 0
        for d in range(maxdepth + 1):
            if cntd[d] >= 2:
                cur = d
            best2[d] = cur
        ans = []
        for w in words:
            node = 0
            dp = 0
            dq = 0 if cnt[0] >= k + 1 else 0
            d = 0
            for ch in w:
                node = children[node][ch]
                d += 1
                c = cnt[node]
                if c >= k:
                    dp = d
                    if c >= k + 1:
                        dq = d
                else:
                    break
            cand = maxd if maxd > dp else best2[dp]
            res = cand
            if dq > res:
                res = dq
            ans.append(res if res > 0 else 0)
        return ans

