class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byB = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            byB[b].append((a, i))
        best1val = 0
        best1id = -1
        best2val = 0
        gain = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for a, i in byB[r]:
                if a > best1val:
                    best2val = best1val
                    best1val = a
                    best1id = i
                elif a > best2val:
                    best2val = a
            base += r - best1val
            if best1id >= 0:
                gain[best1id] += best1val - best2val
        return base + (max(gain) if gain else 0)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        word = [None] * L
        fixed = [False] * L
        s2 = list(str2)
        prev_end = 0
        for i in range(n):
            if str1[i] == 'T':
                start = i if i > prev_end else prev_end
                if start > i:
                    if word[i:start] != s2[:start - i]:
                        return ""
                if start < i + m:
                    word[start:i + m] = s2[start - i:]
                    fixed[start:i + m] = [True] * (i + m - start)
                if i + m > prev_end:
                    prev_end = i + m
        for k in range(L):
            if word[k] is None:
                word[k] = 'a'
        for i in range(n):
            if str1[i] == 'F':
                if word[i:i + m] == s2:
                    j = i + m - 1
                    while j >= i and fixed[j]:
                        j -= 1
                    if j < i:
                        return ""
                    # word[j] currently equals s2[j-i]; choose smallest different char
                    word[j] = 'b' if s2[j - i] == 'a' else 'a'
                    fixed[j] = True
        return ''.join(word)

