class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [x for x in range(1, n+1) if x % 2 == 1]
        evens = [x for x in range(1, n+1) if x % 2 == 0]
        O, E = len(odds), len(evens)

        if n == 1:
            return [1] if k == 1 else []

        base = factorial(O) * factorial(E)
        if n % 2 == 1:
            total = base
        else:
            total = 2 * base

        if k > total:
            return []

        # determine starting parity
        if n % 2 == 1:
            start_odd = True
        else:
            if k <= base:
                start_odd = True
            else:
                start_odd = False
                k -= base

        res = []
        cur_odd = start_odd
        for pos in range(n):
            if cur_odd:
                lst = odds
            else:
                lst = evens
            # after choosing, remaining counts
            if cur_odd:
                ro = len(odds) - 1
                re = len(evens)
            else:
                ro = len(odds)
                re = len(evens) - 1
            cnt = factorial(ro) * factorial(re)
            idx = (k - 1) // cnt
            k -= idx * cnt
            res.append(lst[idx])
            lst.pop(idx)
            cur_odd = not cur_odd

        return res

