def main():
    data = sys.stdin.buffer.read().split()
    H = int(data[0]); W = int(data[1])
    N = H * W
    F = list(map(int, data[2:2 + N]))
    idx = 2 + N
    Q = int(data[idx]); idx += 1
    ints = list(map(int, data[idx:idx + 6 * Q]))

    M2 = 2 * N if N > 1 else 2
    # build edges
    edges = []
    if W > 1:
        for i in range(H):
            base = i * W
            edges.extend([(F[u] if F[u] < F[u+1] else F[u+1]) * M2 + 2 * u
                          for u in range(base, base + W - 1)])
    if H > 1:
        edges.extend([(F[u] if F[u] < F[u+W] else F[u+W]) * M2 + 2 * u + 1
                      for u in range(N - W)])
    edges.sort(reverse=True)

    parent = list(range(N))
    sz = [1] * N
    pend = [None] * N
    ansL = [0] * Q
    Ys = [0] * Q
    Zs = [0] * Q
    remaining = 0

    for qi in range(Q):
        k = 6 * qi
        a = ints[k] - 1; b = ints[k+1] - 1; y = ints[k+2]
        c = ints[k+3] - 1; d = ints[k+4] - 1; z = ints[k+5]
        p = a * W + b; q = c * W + d
        Ys[qi] = y; Zs[qi] = z
        if p == q:
            ansL[qi] = F[p]
        else:
            remaining += 1
            s = pend[p]
            if s is None:
                pend[p] = {qi}
            else:
                s.add(qi)
            s = pend[q]
            if s is None:
                pend[q] = {qi}
            else:
                s.add(qi)

    if remaining:
        for e in edges:
            r = e % M2
            d = r & 1
            u = r >> 1
            v = u + 1 if d == 0 else u + W
            x = u
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            yy = v
            while parent[yy] != yy:
                parent[yy] = parent[parent[yy]]
                yy = parent[yy]
            if x == yy:
                continue
            if sz[x] < sz[yy]:
                x, yy = yy, x
            parent[yy] = x
            sz[x] += sz[yy]
            py = pend[yy]
            if py is not None:
                px = pend[x]
                if px is None:
                    pend[x] = py
                else:
                    if len(px) < len(py):
                        px, py = py, px
                    w = e // M2
                    for qi in py:
                        if qi in px:
                            px.remove(qi)
                            ansL[qi] = w
                            remaining -= 1
                        else:
                            px.add(qi)
                    pend[x] = px
                pend[yy] = None
                if remaining == 0:
                    break

    out = []
    for qi in range(Q):
        y = Ys[qi]; z = Zs[qi]; L = ansL[qi]
        v1 = y - z
        if v1 < 0:
            v1 = -v1
        v2 = y + z - 2 * L
        out.append(v1 if v1 > v2 else v2)
    sys.stdout.write('\n'.join(map(str, out)) + '\n')

