    # outmask[l][c] = mask of j with C[l][j]==c
    outmask = []
    for l in range(n):
        d = {}
        rl = rows[l]
        for j in range(n):
            c = rl[j]
            if c != '-':
                d[c] = d.get(c, 0) | (1 << j)
        outmask.append(d)
    # ingroups[k] = list of (c, list of i) with C[i][k]==c
    ingroups = []
    for k in range(n):
        d = {}
        for i in range(n):
            c = rows[i][k]
            if c != '-':
                if c in d:
                    d[c].append(i)
                else:
                    d[c] = [i]
        ingroups.append(list(d.items()))

