import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        parts = p.split('*')
        a, b, c = parts[0], parts[1], parts[2]
        la, lb, lc = len(a), len(b), len(c)
        if la + lb + lc > n:
            return -1

        def kmp_occ(pat, txt):
            m = len(pat)
            if m == 0:
                return None
            fail = [0]*m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[i] != pat[k]:
                    k = fail[k-1]
                if pat[i] == pat[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i, ch in enumerate(txt):
                while k > 0 and ch != pat[k]:
                    k = fail[k-1]
                if ch == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k-1]
            return res

        posA = kmp_occ(a, s)
        posB = kmp_occ(b, s)
        posC = kmp_occ(c, s)

        if posA is not None and not posA:
            return -1
        if posB is not None and not posB:
            return -1
        if posC is not None and not posC:
            return -1

        if posB is None:
            bList = range(n+1)
        else:
            bList = posB

        ans = float('inf')
        for j in bList:
            # a
            if posA is None:
                a_start = j
            else:
                lim = j - la
                if lim < 0:
                    continue
                idx = bisect.bisect_right(posA, lim) - 1
                if idx < 0:
                    continue
                a_start = posA[idx]
            # c
            need = j + lb
            if posC is None:
                c_end = need
            else:
                idx = bisect.bisect_left(posC, need)
                if idx >= len(posC):
                    continue
                c_end = posC[idx] + lc
            val = c_end - a_start
            if val < ans:
                ans = val
        return ans if ans != float('inf') else -1

