class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        dg = [ord(c) - 48 for c in s]
        # powers of 10 mod 7
        p10 = [1] * (n + 1)
        for i in range(1, n + 1):
            p10[i] = (p10[i - 1] * 10) % 7
        # suffix values mod 7: V[i] = num(s[i..n-1]) mod 7
        V = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            V[i] = (dg[i] * p10[n - 1 - i] + V[i + 1]) % 7
        cnt3 = [0] * 3
        cnt9 = [0] * 9
        cnt7 = [0] * 7
        p3 = 0
        p9 = 0
        ans = 0
        for j in range(n):
            # add index i = j (prefix state pre[j], V[j])
            cnt3[p3] += 1
            cnt9[p9] += 1
            cnt7[V[j]] += 1
            d = dg[j]
            p3 = (p3 + d) % 3
            p9 = (p9 + d) % 9
            if d == 0:
                continue
            if d == 1 or d == 2 or d == 5:
                ans += j + 1
            elif d == 3 or d == 6:
                ans += cnt3[p3]
            elif d == 9:
                ans += cnt9[p9]
            elif d == 7:
                target = (V[j + 1] * p10[n - 1 - j]) % 7
                ans += cnt7[target]
            elif d == 4:
                ans += 1
                if j >= 1 and dg[j - 1] % 2 == 0:
                    ans += j
            elif d == 8:
                ans += 1
                if j >= 1:
                    if (10 * dg[j - 1] + 8) % 8 == 0:
                        ans += 1
                if j >= 2:
                    if (4 * dg[j - 2] + 2 * dg[j - 1]) % 8 == 0:
                        ans += j - 1
        return ans

