class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(T):
            if T == 0:
                return True
            moves = 0
            prev = 0  # visits already accumulated at current index from previous back-and-forth
            for i in range(n):
                need = (T + points[i] - 1) // points[i]
                need -= prev
                if need <= 0:
                    # just move forward
                    if i < n - 1:
                        moves += 1
                    prev = 0
                else:
                    # need 'need' more visits at i
                    # each back-and-forth (go to i+1 and back) gives 1 visit at i and 1 at i+1
                    if i == n - 1:
                        moves += 1 + 2 * (need - 1)
                        prev = 0
                    else:
