class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        full = (1 << k) - 1
        L = [1] * (1 << k)
        for s in range(1, 1 << k):
            l = 1
            for i in range(k):
                if s >> i & 1:
                    t = target[i]
                    l = l // gcd(l, t) * t
            L[s] = l
        # precompute transitions
        trans = []
        for mask in range(1 << k):
            comp = full ^ mask
            sub = comp
            while sub:
                trans.append((mask, sub, mask | sub))
                sub = (sub - 1) & comp
        INF = float('inf')
        dp = [INF] * (1 << k)
        dp[0] = 0
        for num in nums:
            cost = [0] * (1 << k)
            for s in range(1, 1 << k):
                l = L[s]
                cost[s] = (l - num % l) % l
            newdp = dp[:]
            for mask, s, nm in trans:
                d = dp[mask]
                if d < INF:
                    v = d + cost[s]
                    if v < newdp[nm]:
                        newdp[nm] = v
            dp = newdp
            if dp[full] == 0:
                return 0
        return dp[full]

