    return True

def pollard(n):
    if n % 2 == 0:
        return 2
    while True:
        x = random.randrange(2, n)
        y = x
        c = random.randrange(1, n)
        d = 1
        while d == 1:
            x = (x*x + c) % n
            y = (y*y + c) % n
            y = (y*y + c) % n
            d = math.gcd(abs(x-y), n)
        if d != n:
            return d

# small primes
def sieve(lim):
    bs = bytearray([1])*(lim+1)
    bs[0]=bs[1]=0
    for i in range(2,int(lim**0.5)+1):
        if bs[i]:
            bs[i*i::i] = bytearray(len(bs[i*i::i]))
    return [i for i in range(lim+1) if bs[i]]

SMALL = sieve(300)
PRIMS100 = sieve(200)
PRIM = 1
for p in PRIMS100:
    PRIM *= p

def factorize(n):
    fs = set()
    for p in SMALL:
        if p*p > n:
            break
        if n % p == 0:
            fs.add(p)
            while n % p == 0:
                n //= p
    if n > 1:
        stack = [n]
        while stack:
            m = stack.pop()
            if m == 1:
                continue
            if is_prime(m):
                fs.add(m)
                continue
            d = pollard(m)
            stack.append(d)
            stack.append(m//d)
    return fs

def find_prime(step):
    p = step + 1
    while True:
        if p < 1000000:
            if is_prime(p):
                return p
        else:
            if math.gcd(p, PRIM) == 1 and is_prime(p):
                return p
        p += step

