def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1]); A = int(data[2]); B = int(data[3])
    FULL = (1 << B) - 1
    JM = (1 << B) - (1 << (A - 1))  # bits A-1 .. B-1

    def advance(mask, L):
        # advance free region of length L (L steps), return new mask
        if mask == 0:
            return 0
        if L == 0:
            return mask
        if L <= 2 * B:
            for _ in range(L):
                mask = ((mask << 1) | (1 if mask & JM else 0)) & FULL
            return mask
        for _ in range(B):
            mask = ((mask << 1) | (1 if mask & JM else 0)) & FULL
        if mask == 0:
            return 0
        r = L - B
        rev = 0
        tot = 2 * B - 1
        for u in range(tot):
            d = r + B - 1 - u
            if d > 0:
                k = -(-d // B)
                if k * A <= d:
                    rev |= 1 << u
            elif d == 0:
                rev |= 1 << u
        new = 0
        for k in range(B):
            if (mask >> k) & 1:
                new |= rev >> (B - 1 - k)
        return new & FULL

    pos = 1
    mask = 1  # bit0 = position pos reachable

    idx = 4
    ok = True
    for _ in range(M):
        Lv = int(data[idx]); Rv = int(data[idx + 1]); idx += 2
        free_len = Lv - 1 - pos
        if free_len > 0:
            mask = advance(mask, free_len)
        elif free_len < 0:
            # shouldn't happen given constraints
            free_len = 0
        pos = Lv - 1
        if mask == 0:
            ok = False
            break
        bad_len = Rv - Lv + 1
        if bad_len >= B:
            mask = 0
        else:
            mask = (mask << bad_len) & FULL
        pos = Rv
        if mask == 0:
            ok = False
            break

    if not ok:
        sys.stdout.write("No\n")
        return

    free_len = N - pos
    if free_len > 0:
        mask = advance(mask, free_len)
