from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        idx = [-1] * (T + 1)
        cnt_big = 0
        k = 0
        for v in nums:
            if v <= T:
                idx[v] = k
                k += 1
            else:
                cnt_big += 1
        if k == 0:
            return cnt_big
        parent = list(range(k))

        def find(x):
            p = parent
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x

        comp = k
        for d in range(1, T + 1):
            sub = idx[d::d]  # sub[j] corresponds to value d*(j+1)
            j0 = -1
            for j, v in enumerate(sub):
                if v >= 0:
                    j0 = j
                    break
            if j0 < 0:
                continue
            m = d * (j0 + 1)
            end = T // m  # slice end index (exclusive)
            if end <= j0 + 1:
                continue
            rm = find(sub[j0])
            for i in sub[j0 + 1:end]:
                if i >= 0:
                    r = find(i)
                    if r != rm:
                        parent[r] = rm
                        comp -= 1
        return comp + cnt_big
